Object.assign(window.CONTEXTS,{"111-3-49-50":{"text":"阿珍正忙著完成專題製作，為了在課餘時間方便與小組成員討論進度，她想到可以使用 ① 建立線\n上討論室，並使用 ② 建立一份文件存在雲端，組員可隨時共同編輯此文件；為了完整呈現專題成果，\n小組成員一起拍了專題簡介影片，並使用 ③ 完成剪輯工作，最後上傳到 ④ 影音平台與全班同學分\n享。"}});
window.QUESTIONS.push(...[{"id":"111-3-A-26","exam":"111-3","q":26,"unit":"電子商務與數位服務","topic":"數位科技","stem":"我們日常生活中充斥著各種人臉辨識的應用，例如：智慧家庭的門禁管制；在 Facebook 上傳照片時，\n系統可自動判斷，並標記照片中的人臉是哪位好友；還有 Google 相簿提供的人物功能，可將同一個人\n過去和現在的照片分類擺放在一起。請問最有可能是因下列何種數位科技的快速發展？","options":["電子商務","擴增實境","物聯網","人工智慧"],"answer":"D","official":"隨著人工智慧技術的發展，電腦可自動擷取臉部特徵\n值與事先登錄的人臉影像進行分析比對"},{"id":"111-3-A-27","exam":"111-3","q":27,"unit":"電腦與數位資料","topic":"數位科技","stem":"下列何種記憶體，當電源關掉後，記憶體內儲存的資料會隨之消失？","options":["快閃記憶體(flash memory)","快取記憶體(cache memory)","可程式化唯讀記憶體(PROM)","電子可抹除可程式化唯讀記憶體(EEPROM)"],"answer":"B","official":"快取記憶體亦稱 SRAM，雖不需要不斷充電以保持資\n料不流失，但當電源切斷後，所有儲存於其上的資料\n仍會馬上消失"},{"id":"111-3-A-28","exam":"111-3","q":28,"unit":"雲端與新興科技","topic":"數位科技","stem":"下列何者沒有提供雲端服務模式中的 PaaS(Platform as a Service)資源？","options":["Microsoft Azure","Oracle Cloud","Google Drive","Amazon Web Services"],"answer":"C","official":"Google Drive 為 Google 公司提供的服務，內含雲端硬\n碟及表單建立等功能，屬於 SaaS"},{"id":"111-3-A-29","exam":"111-3","q":29,"unit":"作業系統與軟體","topic":"數位科技","stem":"「公用程式」是用來支援電腦作業系統和維護電腦效能的軟體，下列何者可以歸類為公用程式？","options":["磁碟清理工具","校務行政系統","文書處理軟體","網頁瀏覽器"],"answer":"A","official":"磁碟清理工具可協助清除暫存檔等用不到的檔案，增\n加硬碟空間及提升電腦運行速度"},{"id":"111-3-A-30","exam":"111-3","q":30,"unit":"網路與通訊","topic":"數位科技","stem":"有關網路設備的敘述，下列何者錯誤？","options":["橋接器可連接同一個網路中的不同區段，且透過辨識目的地 MAC 位址來達成過濾封包的功能","路由器內建路由表，可根據 IP 位址選擇最佳的封包傳送路徑","閘道器可連接使用不同通訊協定的多個網路","交換器可連結區域網路中多部電腦設備，屬於網路層設備"],"answer":"D","official":"(D) 交換器透過解析目的封包的 MAC 位址與連接埠\n來轉送資料，屬於資料連結層設備"},{"id":"111-3-A-31","exam":"111-3","q":31,"unit":"資安與資訊倫理","topic":"數位科技","stem":"為避免在網際網路中傳輸的資料被竊取，可先將資料在傳送端加密後送出，接收端收到後再進行解密。\n上述功能是由 OSI 架構中的哪一層負責？","options":["應用層","表達層","會議層","傳輸層"],"answer":"B","official":"表達層負責的功能包含：格式轉換、加密及解密與壓\n縮及解壓縮"},{"id":"111-3-A-32","exam":"111-3","q":32,"unit":"電子商務與數位服務","topic":"數位科技","stem":"阿家在製作專題過程中，進入國家圖書館網站搜尋相關文獻作為參考資料，其中國家圖書館的網址為\n「https://www.ncl.edu.tw/」。請問下列敘述何者錯誤？","options":["網址中未顯示埠位址，代表使用預設埠位址為 21","網址中的 edu 代表機構的類別","網址中的 www 是主機名稱","網址開頭 https 是種加密通訊協定"],"answer":"A","official":"(A) https 通訊協定預設的埠號是 443"},{"id":"111-3-A-33","exam":"111-3","q":33,"unit":"網路與通訊","topic":"數位科技","stem":"OTT 服務(Over-the-top media services)，是種將內容與服務架設在網際網路之上，提供用戶串流媒體的一\n項新興服務，下列何者不是 OTT 所提供之服務？","options":["Netflix","Spotify","Podcast","FTP"],"answer":"D","official":"FTP 為檔案傳輸協定，負責規範兩台電腦間檔案下載\n與上傳的規則"},{"id":"111-3-A-34","exam":"111-3","q":34,"unit":"網路與通訊","topic":"數位科技","stem":"阿華於高三畢業後順利進入自己心目中理想的大學就讀，在報到時學校提供一組個人網路電子郵件信\n箱「sm123@mail.nuk.edu.tw」，讓他在大學就讀期間可利用網頁瀏覽器收發信件。請問下列敘述何者\n錯誤？","options":["「sm123」為阿華的網路電子郵件帳號","「mail.nuk.edu.tw」為此大學的郵件伺服器位址","此大學的郵件伺服器採用 SMTP 協定來收信","阿華可使用電腦、平板或智慧型手機，連線至郵件伺服器讀取信件內容"],"answer":"C","official":"SMTP 的全名是 Simple Mail Transfer Protocol，主要\n功能是把郵件傳送到收件者的郵件主機"},{"id":"111-3-A-35","exam":"111-3","q":35,"unit":"雲端與新興科技","topic":"數位科技","stem":"有關物聯網的敘述，下列何者正確？","options":["物聯網的架構可劃分為實體層、網路層與應用層","物聯網可應用於貨運物流業，作為管理與辨識包裹等用途","網路層的關鍵技術包含雲端運算與巨量資料分析","應用層是由許多不同功能的感測器所組成"],"answer":"B","official":"(A) 物聯網架構分為感知層、網路層及應用層\n(C) 網路層著重 WiFi、Zigbee 等網路連線功能\n(D) 由許多不同功能感測器組成的是感知層"},{"id":"111-3-A-36","exam":"111-3","q":36,"unit":"電子商務與數位服務","topic":"數位科技","stem":"共享經濟(The Sharing Economy)是種新興的電子商務模式，利用網際網路作為媒介，使個人或公司企業\n可以用合理的價格，透過出租或共用的方式與他人共享資源。請根據以上描述，判斷下列何者最可能採\n用 P2P(Peer-to-Peer)個人對個人的經營模式？","options":["Airbnb 房間共享","WeMo Scooter 電動機車共享","YouBike 單車共享","iRent 汽機車共享"],"answer":"A","official":"Airbnb 功能為房東將其房子中的閒置空間出租給租\n客，為採用 P2P 模式的應用"},{"id":"111-3-A-37","exam":"111-3","q":37,"unit":"電子商務與數位服務","topic":"數位科技","stem":"有關行動商務的敘述，下列何者錯誤？","options":["cookie 是一種儲存使用紀錄的文字檔，可依此提供個人化服務","透過行動裝置內建的 GPS，可提供使用者適地性服務(LBS)","使用 QR Code 二維條碼來完成行動支付，可降低信用卡資料被店家竊取的機會","iPhone 中的 Apple Pay 功能，可透過 RFID 技術提供使用者以感應的方式付款"],"answer":"D","official":"(D) 當在進行感應式付款時，Apple Pay 會使用近距離\n無線通訊(NFC)技術來完成付款動作"},{"id":"111-3-A-38","exam":"111-3","q":38,"unit":"電子商務與數位服務","topic":"數位科技","stem":"電子商務藉由網際網路為商家與消費者建立起一個新的購物平台，其帶來的效益最不可能是下列何者？","options":["消費者可取得豐富多元的購物資訊","消費者可省去交通成本","商家營運成本增加","商家可將商品銷往各地"],"answer":"C","official":"(C) 電子商店的設立可減少實體店面的營運成本，且\n不一定須提前備貨，可節省倉儲成本"},{"id":"111-3-A-39","exam":"111-3","q":39,"unit":"網路與通訊","topic":"數位科技","stem":"為避免使用者誤觸到網路上流竄的煽情露骨等不當內容，下列何者不是較有效的防範方法？","options":["開啟 YouTube 的嚴格篩選模式","開啟 Chrome 瀏覽器中的 Google 安全搜尋功能","安裝教育部網路守護天使","開啟 Microsoft Defender 功能"],"answer":"D","official":"(D) Microsoft Defender 為防毒軟體，無法過濾不當\n內容"},{"id":"111-3-A-40","exam":"111-3","q":40,"unit":"電腦與數位資料","topic":"數位科技","stem":"高危險性的工作，如：動手術或飛機駕駛，常藉由電腦程式模擬的方式來進行教學訓練，是透過下列哪\n一項技術來達成？","options":["GPS(Global Positioning System)","CAM(Computer Aided Manufacturing)","VR(Virtual Reality)","FinTech(Financial Technology)"],"answer":"C","official":"透過虛擬實境 VR(Virtual Reality)的技術，可讓使用者\n體驗真實環境"},{"id":"111-3-A-41","exam":"111-3","q":41,"unit":"文書與簡報","topic":"數位科技","stem":"在 Microsoft Word 中，當開啟「顯示編輯標記」時，文件中出現「 」符號代表什麼意思？","options":["定位點","分行符號","分段符號","分欄符號"],"answer":"A","scan":"data:image/webp;base64,"},{"id":"111-3-A-42","exam":"111-3","q":42,"unit":"文書與簡報","topic":"數位科技","stem":"在 Microsoft Word 中，當表格資料內容太多需要多頁呈現時，為了便於讀者閱讀，可以透過下列何種功\n能，讓每頁都能顯示表格標題？","options":["重複標題列","項目標記","插入註腳","快速組件"],"answer":"A"},{"id":"111-3-A-43","exam":"111-3","q":43,"unit":"文書與簡報","topic":"數位科技","stem":"在 Microsoft Word 中，使用自訂目錄功能建立的目錄預設具有超連結，請問使用者應按住鍵盤上的哪顆\n鍵，並按下滑鼠左鍵後，文件可跳至對應標題的所在位置？","options":["Alt 鍵","Ctrl 鍵","F9","Shift 鍵"],"answer":"B","official":"在 Microsoft Word 中可使用「Ctrl ＋ 滑鼠左鍵」追蹤\n超連結"},{"id":"111-3-A-44","exam":"111-3","q":44,"unit":"文書與簡報","topic":"數位科技","stem":"在 Microsoft PowerPoint 中，下列敘述何者錯誤？","options":["套用自訂動畫功能，可使投影片中的物件具有飛入動態效果","簡報存成.ppsx 格式，開啟後可直接進入投影片放映模式","透過投影片母片調整版面配置，可一次調整所有套用該版面配置的投影片","將影片檔案以連結方式插入投影片後，即使此檔案的儲存位置改變也不會影響影片的播放"],"answer":"D","official":"(D) 如以連結方式插入檔案，當儲存位置改變時會發\n生找不到檔案的狀況，以嵌入方式才不會受路徑改變\n影響"},{"id":"111-3-A-45","exam":"111-3","q":45,"unit":"試算表與資料處理","topic":"數位科技","stem":"阿仁負責幫到校的同學量額溫並使用 Microsoft Excel 做紀錄，在 Excel 中，欲將額溫超過 37 度的紀錄\n以紅底白字的樣式呈現，作為提醒同學注意自身健康之用，透過下列哪種方式可最快完成？","options":["利用取代功能","透過資料剖析來完成","設定格式化條件","利用排序與篩選"],"answer":"C","official":"利用格式化條件設定，設定規則「當儲存格值大於\n37 時，則修改格式為紅底白字」"},{"id":"111-3-A-46","exam":"111-3","q":46,"unit":"試算表與資料處理","topic":"數位科技","stem":"在 Microsoft Excel 中，若將儲存格 C4 複製並貼到儲存格 E3，發現儲存格 E3 顯示公式「=C$1+$B2」，\n則儲存格 C4 設定的公式為何？","options":["=A$1+$B3","=A$1+$B4","=C$1+$B3","=C$1+$B4"],"answer":"A"},{"id":"111-3-A-47","exam":"111-3","q":47,"unit":"試算表與資料處理","topic":"數位科技","stem":"在 Microsoft Excel 中，使用進階篩選功能時，資\n料與設定的篩選準則如圖(一)所示，請問篩選結\n果共有幾筆資料？","options":["4 筆","5 筆","6 筆","7 筆"],"answer":"B","official":"此篩選準則代表的意義為：篩選出「男生且年齡大於\n17」或「體重小於 75」，共 5 筆資料","scan":"data:image/webp;base64,"},{"id":"111-3-A-48","exam":"111-3","q":48,"unit":"試算表與資料處理","topic":"數位科技","stem":"在 Microsoft Excel 中，儲存格 C2 到 C8 的內容依序為 13、9、10、7、18、6 及 12，請問在儲存格 C9\n輸入公式「=INT(ROUNDUP(AVERAGE(C2:C6,C8),1))」，執行後的結果為何？","options":["9","10","11","12"],"answer":"C","official":"= INT(ROUND(AVERAGE(13,9,10,7,18,12),1))\n= INT(ROUND(11.5,1))= INT(11.5)=11"},{"id":"111-3-A-49","exam":"111-3","q":49,"unit":"電腦與數位資料","topic":"數位科技","stem":"過程中阿珍共使用四種不同功能的電腦軟體來完成專題製作，下列對應關係何者錯誤？","options":["①：Microsoft Teams","②：Google Docs","③：SketchUp","④：YouTube"],"answer":"C","official":"(C) SketchUp 為 3D 設計軟體","group":"111-3-49-50"},{"id":"111-3-A-50","exam":"111-3","q":50,"unit":"資安與資訊倫理","topic":"數位科技","stem":"阿珍要將上傳的影片，設定以「姓名標示-相同方式分享」來授權自己組別的專題創作，請問她該使用\n下列何種創用 CC 標示？","options":["","","","圖(一)"],"answer":"B","official":"(A) 姓名標示-禁止改作\n(C) 姓名標示-非商業性\n(D) 姓名標示-非商業性-禁止改作","group":"111-3-49-50","scan":"data:image/webp;base64,"}]);
